// Nursing Assisting Practice Test 1. Original questions written for Valus from the HOSA 2026–27 test
// plan, slightly harder than the sample items: the reasons behind care procedures and what to report.
import {q, mix} from './q.js';
const DUG='Dugan, Nursing Assisting: A Foundation in Caregiving', ROE='Roe, The Nursing Assistant: Essentials of Holistic Care';
const ROLE='Nursing Assistant Roles and Responsibilities', AP='Anatomy and Physiology', INF='Infection Control/Safety', COMM='Communication/Culture', CARE='Providing and Reporting Care', DIS='Disabilities and Disorders';

export default {
 id:'nursing-assisting-1',
 event:'Nursing Assisting',
 title:'Practice Test 1',
 subtitle:'Full-length Round One simulation',
 minutes:60,
 sources:'Dugan’s Nursing Assisting: A Foundation in Caregiving and Roe’s The Nursing Assistant',
 plan:[{area:ROLE,weight:6},{area:AP,weight:20},{area:INF,weight:14},{area:COMM,weight:10},{area:CARE,weight:30},{area:DIS,weight:20}],
 questions:mix([
  q(ROLE,'Which task is outside a nursing assistant’s scope of practice?','Giving medications',['Measuring vital signs','Helping with bathing','Recording intake and output'],'B','Nursing assistants do not give medications, perform sterile procedures or make diagnoses. They report observations to the nurse.',DUG),
  q(ROLE,'Under the Omnibus Budget Reconciliation Act (OBRA), what must a nursing assistant complete before working in a long-term care facility?','75+ hours of training and a competency test',['A two-year associate degree','A national board exam in registered nursing','A one-week hospital orientation only'],'D','OBRA (1987) requires at least 75 hours of training, including supervised clinical practice, and passing a competency evaluation to be listed on the state registry.',DUG),
  q(ROLE,'A nurse asks a nursing assistant to perform a task the assistant was never trained to do. What should the assistant do?','Explain the lack of training and decline',['Do the task and ask questions later','Ask another assistant to do it secretly','Ignore the request'],'A','Nursing assistants may refuse a delegated task that is outside their training or job description, but they must tell the nurse promptly so the care still gets done.',DUG),
  q(AP,'Which layer of the skin has no blood vessels?','Epidermis',['Dermis','Subcutaneous layer','Hypodermis'],'C','The epidermis, the outer layer, gets nutrients by diffusion from the dermis below, which contains blood vessels, nerves and glands.',ROE),
  q(AP,'Which chamber of the heart pumps oxygen-rich blood out to the body?','Left ventricle',['Right atrium','Right ventricle','Left atrium'],'B','The left ventricle has the thickest wall because it pumps blood through the aorta to the whole body. The right ventricle pumps blood to the lungs.',ROE),
  q(AP,'Where does the exchange of oxygen and carbon dioxide take place in the lungs?','Alveoli',['Bronchi','Trachea','Pleura'],'D','Alveoli are tiny air sacs surrounded by capillaries. Oxygen moves into the blood and carbon dioxide moves out across their thin walls.',ROE),
  q(AP,'Which structures in the kidneys filter the blood to form urine?','Nephrons',['Ureters','Alveoli','Neurons'],'A','Each kidney contains about a million nephrons that filter waste and excess water from the blood. Ureters carry urine from the kidneys to the bladder.',ROE),
  q(AP,'Which organ produces insulin?','Pancreas',['Liver','Thyroid','Adrenal gland'],'C','Beta cells in the pancreas produce insulin, which helps glucose enter cells. Lack of insulin or resistance to it causes diabetes.',ROE),
  q(AP,'What makes up the central nervous system?','The brain and spinal cord',['The nerves of the arms and legs','The brain and the cranial nerves','The spinal cord and the heart'],'B','The central nervous system is the brain and spinal cord. The peripheral nervous system includes the nerves that branch out to the rest of the body.',ROE),
  q(AP,'A resident on bed rest for weeks develops thin, weak leg muscles. What is this called?','Atrophy',['Contracture','Hypertrophy','Spasm'],'D','Disuse atrophy is the wasting of muscle from lack of use. A contracture is a permanent shortening of a muscle that limits joint movement.',DUG),
  q(AP,'What moves food through the digestive tract?','Peristalsis',['Absorption','Emulsification','Mastication'],'A','Peristalsis is the wave-like contraction of smooth muscle that pushes food along. Mastication is chewing.',ROE),
  q(AP,'Why do many older adults need to urinate more often?','Bladder capacity and muscle tone decrease with age',['The kidneys make more urine with age','The urethra becomes longer with age','Older adults drink more water than younger adults'],'C','Aging reduces bladder capacity and the bladder’s ability to empty completely, so older adults urinate more often and may get up at night.',DUG),
  q(AP,'What is the main function of red blood cells?','Carrying oxygen',['Fighting infection','Forming blood clots','Producing antibodies against germs'],'B','Red blood cells contain hemoglobin, which carries oxygen from the lungs to the tissues. White blood cells fight infection, and platelets help blood clot.',ROE),
  q(INF,'What is the single most important way to break the chain of infection?','Hand hygiene',['Wearing a gown at all times','Giving antibiotics','Keeping windows closed'],'D','Hand hygiene breaks the mode of transmission, the link most easily controlled. It is done before and after every resident contact and after removing gloves.',DUG),
  q(INF,'A resident has active tuberculosis. Which precautions and equipment are needed?','Airborne precautions with an N95 respirator',['Contact precautions with gloves only','Droplet precautions with a surgical mask','Standard precautions only'],'A','TB spreads through tiny airborne particles. Airborne precautions require a fit-tested N95 respirator and an airborne infection isolation room with negative pressure.',DUG),
  q(INF,'After caring for a resident with Clostridioides difficile (C. diff), how should the assistant clean their hands?','Soap and water',['Alcohol-based hand rub','Antiseptic wipes only','No hand hygiene is needed if gloves were worn'],'C','Alcohol does not kill C. diff spores. Washing with soap and water physically removes them. Contact precautions with gown and gloves are also used.',DUG),
  q(INF,'What is the correct order for putting on personal protective equipment?','Gown, mask, goggles, gloves',['Gloves, gown, mask, goggles','Mask, gloves, gown, goggles','Goggles, gloves, mask, gown'],'B','PPE is put on gown first and gloves last so the gloves cover the gown cuffs. It is removed starting with the most contaminated item, the gloves.',DUG),
  q(INF,'A small fire starts in a resident’s room. What should the nursing assistant do first?','Rescue the resident',['Pull the fire alarm','Close all the doors','Get the fire extinguisher'],'D','RACE: Rescue anyone in danger, Alarm (activate the alarm), Contain the fire by closing doors, then Extinguish if it is small and safe to do so.',DUG),
  q(INF,'A resident has a physician-ordered restraint. How often must the restraint be released?','Every 2 hours',['Once per shift','Only at mealtimes','Once a day'],'A','Restraints are a last resort. The resident is checked at least every 15 minutes, and the restraint is released at least every 2 hours for movement, toileting, fluids and skin care.',DUG),
  q(INF,'Which action best reduces a resident’s risk of falling?','Keep the bed in its lowest position',['Keep all bed rails raised at night','Leave the lights off to help sleep','Place the call light out of reach'],'C','A low bed, a call light within reach, nonskid footwear, good lighting and frequent checks reduce falls. Bed rails can increase injury if residents climb over them.',ROE),
  q(COMM,'Which question is open-ended and encourages a resident to talk?','“How did you sleep?”',['“Did you sleep well?”','“Are you in pain?”','“Do you want juice?”'],'B','Open-ended questions cannot be answered with yes or no, so they invite more information. Closed questions are useful for quick facts.',DUG),
  q(COMM,'Which technique helps a resident with a hearing impairment understand you?','Face them and speak clearly at a lower pitch',['Shout directly into the resident’s ear','Talk while walking out of the room','Cover your mouth to keep it private'],'D','Facing the resident allows lip reading. Speaking clearly in a lower tone helps, because high-pitched sounds are often lost first. Shouting distorts speech.',DUG),
  q(COMM,'A resident has expressive aphasia after a stroke. Which approach helps most?','Use yes-or-no questions and pictures',['Speak loudly and quickly','Finish all of the resident’s sentences','Avoid talking to the resident'],'A','Expressive aphasia makes it hard to speak or find words. Simple yes-or-no questions, gestures and communication boards let the resident respond. Be patient and do not rush.',DUG),
  q(COMM,'How should a nursing assistant handle cultural differences in personal space and eye contact?','Learn the resident’s preferences and respect them',['Treat every resident exactly the same way','Insist that residents follow facility customs','Avoid residents from other cultures'],'C','Comfort with touch, distance and eye contact varies by culture and person. Observing and asking about preferences shows respect and builds trust.',ROE),
  q(COMM,'A resident says, “I feel dizzy.” How is this information classified?','Subjective information',['Objective information','A sign','A diagnosis'],'B','Subjective information is what the resident reports and cannot be directly observed. Objective information, or signs, can be seen, heard, felt or measured, such as a pulse rate.',DUG),
  q(CARE,'What is the normal pulse range for a resting adult?','60–100 beats per minute',['40–60 beats per minute','100–140 beats per minute','20–40 beats per minute'],'D','A resting adult pulse is 60–100 beats per minute. A rate below 60 (bradycardia) or above 100 (tachycardia) should be reported.',DUG),
  q(CARE,'Why should a nursing assistant count respirations without telling the resident?','People change their breathing when watched',['Residents may refuse to let you count','Counting aloud makes breathing faster','It saves time when taking all the vital signs'],'A','Breathing can be controlled voluntarily. Counting while still holding the wrist after the pulse keeps the resident unaware and the count accurate.',DUG),
  q(CARE,'What happens if a blood pressure cuff is too small for the resident’s arm?','The reading will be falsely high',['The reading will be falsely low','The reading will not be affected','The pulse cannot be heard at all'],'C','A cuff that is too small needs more pressure to compress the artery, so the reading is falsely high. A cuff that is too large gives a falsely low reading.',DUG),
  q(CARE,'How long should a nursing assistant wait to take an oral temperature after a resident drinks a hot beverage?','15 minutes',['1 minute','5 minutes','60 minutes'],'B','Eating, drinking, smoking or chewing gum changes mouth temperature. Waiting 15 minutes gives an accurate oral reading.',DUG),
  q(CARE,'How often should a resident who cannot move independently be repositioned to prevent pressure injuries?','At least every 2 hours',['Every 8 hours','Once per shift','Only when the resident asks'],'D','Pressure on bony areas reduces blood flow to the skin. Repositioning at least every 2 hours, or more often if ordered, relieves pressure.',DUG),
  q(CARE,'In which position is the head of the bed raised 45 to 60 degrees?','Fowler’s position',['Supine position','Sims’ position','Prone position'],'A','Fowler’s position helps breathing and eating. Semi-Fowler’s is about 30–45 degrees, high Fowler’s about 60–90 degrees, and Sims’ is a side-lying position.',DUG),
  q(CARE,'When giving perineal care to a female resident, in which direction should you clean?','From front to back',['From back to front','In circles starting at the anus','In any direction'],'C','Cleaning from front to back, using a clean area of the washcloth for each stroke, keeps bacteria from the anal area away from the urethra and helps prevent infection.',DUG),
  q(CARE,'A resident drinks 8 oz of milk and 4 oz of juice at breakfast. How many mL should be recorded on the intake record?','360 mL',['120 mL','240 mL','480 mL'],'B','1 oz = 30 mL. 8 oz + 4 oz = 12 oz, and 12 × 30 = 360 mL. Intake is recorded in mL so totals can be compared with output.',DUG),
  q(CARE,'How should a resident with swallowing problems be positioned for meals?','Upright at 90 degrees',['Lying flat on the back','Reclined at about 30 degrees','Lying on the left side'],'D','Sitting fully upright, with the chin slightly tucked, helps food go down the esophagus rather than into the airway. The resident should stay upright for about 30 minutes after eating.',DUG),
  q(CARE,'During passive range-of-motion exercises, the resident says the movement hurts. What should you do?','Stop the movement and report it to the nurse',['Push gently past the pain','Repeat the movement faster','Skip that joint for the rest of the week'],'A','Joints are moved only to the point of resistance or pain. Pain should be reported so the nurse can assess the resident.',DUG),
  q(CARE,'A resident has weakness on the left side from a stroke. Where should the wheelchair be placed for a transfer from the bed?','On the resident’s right (strong) side',['On the resident’s left (weak) side','At the foot of the bed','Behind the resident'],'C','Placing the wheelchair on the strong side lets the resident lead and pivot with the stronger leg. A gait belt is used for safety.',DUG),
  q(CARE,'When dressing a resident with a weak right arm, which arm should go into the shirt first?','The weak right arm',['The strong left arm','Either arm, whichever is easier','Both arms at the same time'],'B','Dress the weak side first and undress the strong side first. This uses the fewest movements of the affected limb.',DUG),
  q(CARE,'Why must a urinary drainage bag always be kept below the level of the bladder?','To keep urine from flowing back',['To make the bag easier to empty','To keep the tubing warm and flexible','To measure output more accurately'],'D','Backflow of urine from the bag or tubing can carry bacteria into the bladder and cause infection. The bag is hung on the bed frame, never on the side rail or on the floor.',DUG),
  q(CARE,'Which observation should a nursing assistant report to the nurse immediately?','A resident reports chest pain',['A resident asks for a snack','A resident’s family visits','A resident wants to watch television'],'A','Chest pain may signal a heart attack and needs immediate attention. Any sudden change in condition, such as difficulty breathing or confusion, is reported right away.',DUG),
  q(CARE,'For accurate tracking, how should a resident be weighed each time?','Same time, same scale, similar clothing',['At different times to get an average','On any available scale','Only after meals, when the resident is full'],'C','Using the same conditions every time makes changes in weight meaningful. Sudden weight gain can signal fluid retention, and loss can signal poor nutrition.',ROE),
  q(DIS,'A resident had a stroke on the right side of the brain. Which side of the body is most likely weak?','The left side',['The right side','Both legs only','Only the face'],'B','Each side of the brain controls the opposite side of the body, so a right-brain stroke usually causes left-sided weakness (hemiparesis) or paralysis (hemiplegia).',DUG),
  q(DIS,'A resident with Alzheimer’s disease insists she must go home to feed her children, who are now adults. What is the best response?','Acknowledge her feelings and gently redirect her',['Tell her firmly that her children are grown','Argue until she agrees','Ignore her and leave the room'],'D','Arguing or correcting can increase agitation. Validating her feelings (“You love your children”) and redirecting to a calming activity work better.',DUG),
  q(DIS,'A resident with diabetes is shaky, sweaty and confused before lunch. What should be suspected?','Low blood sugar',['High blood sugar','Dehydration','A urinary tract infection'],'A','These are signs of hypoglycemia, which can develop quickly. Report it to the nurse immediately; the resident may need fast-acting sugar.',DUG),
  q(DIS,'Which breathing technique helps residents with COPD empty their lungs?','Pursed-lip breathing',['Rapid shallow breathing','Holding the breath','Breathing only through the mouth with lips open'],'C','Breathing out slowly through pursed lips keeps the airways open longer, helping trapped air escape and reducing shortness of breath.',DUG),
  q(DIS,'A resident with heart failure gains 3 pounds overnight. Why should this be reported?','It may signal fluid retention',['It shows the resident is eating well','It is normal and expected','It means the scale is broken'],'B','Rapid weight gain in heart failure usually means fluid retention, not fat, and may require medication changes. Daily weights are done at the same time each morning.',DUG),
  q(DIS,'Which signs are typical of Parkinson’s disease?','A resting tremor and a shuffling walk',['Sudden one-sided paralysis','High fever and stiff neck','Memory loss only, with normal movement'],'D','Parkinson’s disease causes tremor at rest, muscle rigidity, slow movement and a shuffling gait. Residents are at high risk for falls.',DUG),
  q(DIS,'A resident had a hip replacement. Which precaution is usually followed?','Do not let the resident cross the legs',['Keep the knees pulled to the chest','Have the resident sit in low, soft chairs','Turn the resident onto the operated side'],'A','Crossing the legs, bending the hip past 90 degrees or turning the leg inward can dislocate the new hip. An abduction pillow may be used between the legs.',DUG),
  q(DIS,'What describes a stage 1 pressure injury?','Intact skin with redness that does not blanch',['An open crater exposing fat tissue','A deep wound that exposes muscle or bone','A shallow blister with an open base'],'C','In stage 1, skin is intact but red and does not blanch. It is reversible if pressure is relieved, so it should be reported right away.',DUG),
  q(DIS,'How should a resident’s hearing aid be cared for at night?','Turn it off and open the battery door',['Leave it in the ear while sleeping','Soak it in water to clean it','Store it in a warm, humid place'],'B','Turning it off and opening the battery compartment saves battery life. Hearing aids are kept dry and stored in a labeled case.',DUG),
  q(DIS,'An older resident has stopped eating, avoids activities and sleeps much of the day. What should the nursing assistant do?','Report the changes to the nurse',['Assume this is normal aging','Tell the resident to cheer up','Wait a month to see if it continues'],'D','Depression is common but not a normal part of aging. Withdrawal and changes in appetite and sleep should be reported so the resident can be assessed and treated.',DUG)
 ],19)
};
